B-cool-light-spine.css:
:root { --bg: #f3f3f4; --panel: #ffffff; --panel-2: #e8e9eb; --line: #dbdcde; --line-strong: #cacccf; --text-3: #686c71; --text-2: #4c5055; --text: #1a1d21; --brand: #387a66; --brand-hover: #1f5c4b; --brand-soft: #e9f7f2; --brand-line: #a5d9c7; --brand-ink: #ffffff; --shell-text: #d4e3dc; --hl: var(--brand-soft); --concl-label: var(--brand); }
 .top { background: var(--panel-2); border-right: 1px solid var(--line); color: var(--text-2); }
 .brand { background: var(--brand); color: #fff; }
 .tab, .top .btn, .top .btn.quiet, .top .chip.profile { color: var(--text-2); }
 .tab:hover, .top .btn:hover:not(:disabled), .top .chip.profile:hover { background: var(--line); color: var(--text); }
 .tab[aria-selected="true"] { background: var(--panel); color: var(--brand); box-shadow: 0 1px 2px rgba(0,0,0,.06); }
 .top .chip.profile b { color: var(--text); } .top .btn[aria-pressed="true"] { color: var(--text); }
 .tab .n { background: var(--brand); color: #fff; } .top :focus-visible { outline-color: var(--brand); }

C-graphite-ink-blue.css:
:root { --bg: #f3f3f4; --panel: #ffffff; --panel-2: #e8e9eb; --line: #dbdcdf; --line-strong: #caccd0; --text-3: #686c73; --text-2: #4c5057; --text: #1a1d21; --brand: #386bb6; --brand-hover: #214e90; --brand-soft: #edf4ff; --brand-line: #aecefd; --brand-ink: #ffffff; --shell-text: #d4e3dc; --hl: var(--brand-soft); --concl-label: var(--brand); }
 .top { background: #1a1d21; } .brand { background: var(--brand); color: #fff; }
 .tab[aria-selected="true"] { background: rgba(255,255,255,.12); } .tab .n { background: #fff; color: #1a1d21; }
